# Spy wrapper around b to count how many BEGINs hit the RESERVED lock
# (sqlite3.Connection attributes are read-only, so we delegate instead).
class CountingConn:
    def __init__(self, inner):
        self._inner = inner
        self.begin_lock_errors = 0

    def execute(self, sql, *args):
        try:
            return self._inner.execute(sql, *args)
        except sqlite3.OperationalError:
            if sql == "BEGIN IMMEDIATE":
                self.begin_lock_errors += 1
            raise

    def __getattr__(self, name):
        return getattr(self._inner, name)

counting_b = CountingConn(b)

def writer(conn):
    writes["n"] += 1

